query GetMatchPicksBans($matchId: Long!) {
  match(id: $matchId) {
    id
    gameMode
    regionId
    durationSeconds
    endDateTime
    lobbyType
    didRadiantWin
    radiantKills
    direKills
    bracket
    radiantTeam {
      id
      name
      __typename
    }
    direTeam {
      id
      name
      __typename
    }
    league {
      id
      displayName
      __typename
    }
    players {
      heroId
      position
      __typename
    }
    pickBans {
      heroId
      order
      isPick
      isRadiant
      bannedHeroId
      wasBannedSuccessfully
      __typename
    }
    __typename
  }
}

query GetMatchCountPreviousWeekDay($bracketIds: [RankBracket]) {
  stratz {
    page {
      matches {
        matchesStatsDay(take: 32, bracketIds: $bracketIds) {
          day
          matchCount
          __typename
        }
        matchesStatsWeek(take: 4, bracketIds: $bracketIds) {
          week
          matchCount
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

